# The registration form's parts of the day; editable afterwards in the admin.
# Evening ends at midnight (an end at or before the start runs past midnight).
EVENT_DAYS = [datetime.date(2027, 1, d) for d in (2, 3, 4, 5)]
PARTS = [
    ("morning", datetime.time(8, 0), datetime.time(12, 0)),
    ("afternoon", datetime.time(12, 0), datetime.time(17, 0)),
    ("evening", datetime.time(17, 0), datetime.time(0, 0)),
]


def seed_time_slots(apps, schema_editor):
    TimeSlot = apps.get_model("schedule", "TimeSlot")
    for day in EVENT_DAYS:
        for part, start, end in PARTS:
            TimeSlot.objects.get_or_create(day=day, part=part, defaults={"start": start, "end": end})


